// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address attacker, uint128 depositAmount, uint128 collectAmount) public {
        vm.assume(attacker != address(0));
        uint256 dep = uint256(depositAmount);
        uint256 col = uint256(collectAmount);
        Attacker a = new Attacker(address(c));

        vm.deal(address(a), dep + 1 ether);

        uint256 beforeMin = 1 ether;
        c.SetMinSum(beforeMin);
        c.SetLogFile(address(a));
        c.Initialized();

        a.setup(attacker);

        vm.prank(address(a));
        (bool s,) = address(c).call{value: dep}('');
        require(s);

        uint256 minBefore = c.MinSum();

        vm.prank(address(a));
        try c.Collect(col) {
        } catch {
        }

        assertTrue(c.MinSum() == minBefore);
    }
}

contract Attacker {
    address public target;
    address public attackerAddr;
    bool public reentered;

    constructor(address _t) {
        target = _t;
    }

    function setup(address _attackerAddr) external {
        attackerAddr = _attackerAddr;
        reentered = false;
    }

    function AddMessage(address, uint, string memory) public {
        if (!reentered) {
            reentered = true;
            (bool s,) = target.call(abi.encodeWithSignature("Collect(uint256)", uint256(0)));
            s;
        }
    }
}
